class StartSchmmi(CommandChangingPrompt):
    """Start schmmi command class."""

    def __init__(
        self, connection, ctrl_number, path="/opt/rtg/bin/schmmi", prompt=None, expected_prompt=r"^\[\w+ @ \w+\]\$", newline_chars=None, runner=None
    ):
        """
        Start schmmi command.

        :param connection: moler connection to device, terminal when command is executed.
        :param ctrl_number: number of controller to connect.
        :param path: path to schmmi file.
        :param prompt: expected prompt sending by device after command execution.
        :param expected_prompt: final prompt.
        :param newline_chars: Characters to split lines.
        :param runner: Runner to run command.
        """
        super(StartSchmmi, self).__init__(connection, prompt=prompt, expected_prompt=expected_prompt, newline_chars=newline_chars, runner=runner)
        self.schmmi_path = path
        self.ctrl_number = ctrl_number

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return f"{self.schmmi_path} {self.ctrl_number}"


